/*
 * latch_secpol_dump.c -- dump the secpolgenerate observation files.
 *
 * DEVELOPMENT-ONLY.  This program is linked ONLY into the disposable
 * secpolgenerate AUDIT image (qnx/latch_qemu_governor_secpol_audit.build,
 * generated by tools/generate_secpol_audit_build.py).  It is NEVER part of
 * the enforced deployment image.
 *
 * WHY IT EXISTS
 * -------------
 * The audit image is a minimal QNX IFS: it has `ksh`, `pidin`, `on`,
 * `slay`, `waitfor` and the LATCH binaries, but NO `cat`, NO `ls` and no
 * `dd`.  The files this audit needs to read live on a pseudo-filesystem
 * that QNX's own utilities do not expose, so the audit needs one small
 * reader.
 *
 * WHY IT IS NOT A PLAIN `cat`
 * ---------------------------
 * `/dev/secpolgenerate/policy` is a STREAM, not a regular file.  The QNX
 * System Security Guide says it plainly: "Because secpolgenerate generates
 * policy content as the file is being read, it does not provide a
 * meaningful file size."
 *
 * HOW IT ENDS
 * -----------
 * The snapshot has to end somehow, and every cheap bound was MEASURED to
 * fail on its own:
 *
 *   - a plain blocking read never returns while the system is alive
 *     (this is what the v12 audit image did, and it worked only because
 *     that image ran the generator WITHOUT `-f`; see the comment in
 *     tools/generate_secpol_audit_build.py);
 *   - `select()` reports the descriptor "readable" and the `read()` then
 *     blocks anyway;
 *   - `O_NONBLOCK` does not help: the resource manager parks the thread
 *     inside the read;
 *   - `SIGALRM` + `alarm()` does NOT interrupt that parked read.
 *
 * So the bound is a CANCELLABLE WORKER THREAD: the worker does the
 * open/read/write and reports its progress, and the main thread cancels it
 * when no progress arrives for IDLE_SECONDS.  `read()` is a cancellation
 * point, so the cancel lands even where a signal does not.
 *
 * The worker uses raw write(2) and no stdio, so a cancellation can never
 * leave a stdio lock held; every formatted line is printed by the main
 * thread.  Each file's byte count and HOW its snapshot ended are REPORTED,
 * so a truncated snapshot is visible in the transcript instead of looking
 * like a complete one.
 *
 * It grants no ability, touches no resource, and has no side effects: it
 * opens five files read-only and writes them to stdout.
 */

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

/* No read progress for this long means the stream is done. */
#define IDLE_SECONDS       5
/* Overall budget for the whole snapshot. */
#define TOTAL_BUDGET_SECONDS 120
/* Hard cap per file, so a busy system cannot make the reader run away. */
#define MAX_BYTES          (256 * 1024)

/* The files to read.  The harness can override this list with arguments,
 * so a single file can be captured with its own bound -- one file that
 * hangs must not block the others. */
static const char *g_paths[16];
static int         g_path_count;

static void add_path(const char *p)
{
    if (g_path_count < (int)(sizeof(g_paths) / sizeof(g_paths[0])) - 1) {
        g_paths[g_path_count++] = p;
    }
}

static const char *const default_paths[] = {
    "/dev/secpolgenerate/policy",
    "/dev/secpolgenerate/errors",
    "/dev/secpolgenerate/unused",
    "/dev/secpolgenerate/request",
    "/dev/secpolgenerate/control",
    NULL
};

/* The worker's progress, shared with the main thread. */
struct progress {
    pthread_mutex_t lock;
    long long       last_progress_ms;   /* CLOCK_MONOTONIC milliseconds */
    int             bytes;              /* bytes of the CURRENT file */
    int             file_index;         /* which file the worker is on */
    int             finished;           /* the worker ran to completion */
    int             cancelled;          /* the worker was cancelled */
    int             open_errno;         /* errno of the current open() */
};

static struct progress g_prog;

static long long now_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

static void note_progress(int bytes)
{
    pthread_mutex_lock(&g_prog.lock);
    g_prog.bytes = bytes;
    g_prog.last_progress_ms = now_ms();
    pthread_mutex_unlock(&g_prog.lock);
}

static void write_all(const char *buf, size_t len)
{
    size_t off = 0;
    while (off < len) {
        ssize_t w = write(STDOUT_FILENO, buf + off, len - off);
        if (w <= 0) {
            return;
        }
        off += (size_t)w;
    }
}

/* The worker: raw open/read/write only.  No stdio, so a cancellation can
 * never strand a stdio lock. */
static void *reader_thread(void *arg)
{
    char buf[4096];

    (void)arg;

    for (int i = 0; i < g_path_count; ++i) {
        const char *path = g_paths[i];

        pthread_mutex_lock(&g_prog.lock);
        g_prog.file_index = i;
        g_prog.bytes = 0;
        g_prog.last_progress_ms = now_ms();
        pthread_mutex_unlock(&g_prog.lock);

        int fd = open(path, O_RDONLY);
        if (fd < 0) {
            pthread_mutex_lock(&g_prog.lock);
            g_prog.open_errno = errno;
            pthread_mutex_unlock(&g_prog.lock);
            continue;
        }
        pthread_mutex_lock(&g_prog.lock);
        g_prog.open_errno = 0;
        pthread_mutex_unlock(&g_prog.lock);

        int total = 0;
        for (;;) {
            ssize_t n = read(fd, buf, sizeof(buf));
            if (n <= 0) {
                break;
            }
            write_all(buf, (size_t)n);
            total += (int)n;
            note_progress(total);
            if (total >= MAX_BYTES) {
                break;
            }
        }
        close(fd);
    }

    pthread_mutex_lock(&g_prog.lock);
    g_prog.finished = 1;
    pthread_mutex_unlock(&g_prog.lock);
    return NULL;
}

int main(int argc, char **argv)
{
    if (argc > 1) {
        for (int i = 1; i < argc; ++i) {
            add_path(argv[i]);
        }
    } else {
        for (int i = 0; default_paths[i] != NULL; ++i) {
            add_path(default_paths[i]);
        }
    }

    pthread_mutex_init(&g_prog.lock, NULL);
    g_prog.last_progress_ms = now_ms();

    pthread_t worker;
    if (pthread_create(&worker, NULL, reader_thread, NULL) != 0) {
        printf("[latch_secpol_dump] pthread_create failed: errno %d (%s)\n",
               errno, strerror(errno));
        return 1;
    }

    const long long start = now_ms();
    int cancelled = 0;

    for (;;) {
        struct timespec ts = { 0, 100 * 1000 * 1000 };   /* 100 ms */
        nanosleep(&ts, NULL);

        pthread_mutex_lock(&g_prog.lock);
        const int finished = g_prog.finished;
        const long long idle_ms = now_ms() - g_prog.last_progress_ms;
        const long long total_ms = now_ms() - start;
        pthread_mutex_unlock(&g_prog.lock);

        if (finished) {
            break;
        }
        if (idle_ms >= (long long)IDLE_SECONDS * 1000LL ||
            total_ms >= (long long)TOTAL_BUDGET_SECONDS * 1000LL) {
            /* The stream has stopped producing.  Cancel the worker: a
             * signal cannot interrupt this read, but a cancellation can. */
            pthread_cancel(worker);
            cancelled = 1;
            break;
        }
    }

    if (cancelled) {
        /* The worker is parked inside read(); give the cancel a moment to
         * land before joining it. */
        struct timespec ts = { 0, 200 * 1000 * 1000 };
        nanosleep(&ts, NULL);
    }
    pthread_join(worker, NULL);

    /* Now report what was captured.  The file boundaries are printed here,
     * by the main thread, so the transcript is well-formed even when the
     * worker was cancelled in the middle of a file. */
    pthread_mutex_lock(&g_prog.lock);
    const int finished = g_prog.finished;
    const int file_index = g_prog.file_index;
    const int bytes = g_prog.bytes;
    const int open_errno = g_prog.open_errno;
    pthread_mutex_unlock(&g_prog.lock);

    printf("[latch_secpol_dump] snapshot ended: %s\n",
           finished ? "the generator closed the stream (EOF)" :
                      "CANCELLED after the idle timeout -- the snapshot is PARTIAL");
    printf("[latch_secpol_dump] files requested: %d; files reached: %d; "
           "last file: %d byte(s)\n",
           g_path_count, finished ? g_path_count : file_index + 1, bytes);
    if (open_errno != 0) {
        printf("[latch_secpol_dump] last open failed: errno %d (%s)\n",
               open_errno, strerror(open_errno));
    }
    printf("===== LATCH_SECPOL_DUMP COMPLETE =====\n");
    fflush(stdout);
    return 0;
}
